import {isFeatureEnabled} from '@github-ui/feature-flags'
import {useAutocompleteTriggersAndSuggestions} from '@github-ui/inline-autocomplete/hooks/use-autocomplete-triggers-and-suggestions'
import type {Suggestion, TriggerAndSuggestions} from '@github-ui/inline-autocomplete/types'
import type {SuggestionOptions} from '@github-ui/markdown-editor/suggestions'
import {type Emoji, useEmojiSuggestions} from '@github-ui/markdown-editor/suggestions/use-emoji-suggestions'
import {type Mentionable, useMentionSuggestions} from '@github-ui/markdown-editor/suggestions/use-mention-suggestions'
import {type Reference, useReferenceSuggestions} from '@github-ui/markdown-editor/suggestions/use-reference-suggestions'
import {ActionList} from '@primer/react'
import {useMemo} from 'react'

const slashCommandsHintSuggestion: Suggestion = {
  key: 'slash-commands',
  value: null,
  render: props => {
    const message = isFeatureEnabled('markdown_experience_toolbar_redesign')
      ? "Switch to 'Edit' mode"
      : "Switch to 'Write' mode"

    return (
      <ActionList.Item {...props}>
        {message}
        <ActionList.Description variant="block">
          Slash commands are not yet available in the hybrid Markdown editor
        </ActionList.Description>
      </ActionList.Item>
    )
  },
}

const slashCommandsConfig: TriggerAndSuggestions = {
  trigger: {
    triggerChar: '/',
    keepTriggerCharOnCommit: true,
  },
  suggestionsCalculator: () => [slashCommandsHintSuggestion],
}

export const useStandardAutocompleteConfig = (
  referenceSuggestions?: SuggestionOptions<Reference>,
  mentionSuggestions?: SuggestionOptions<Mentionable>,
  emojiSuggestions?: SuggestionOptions<Emoji>,
  emojiTone?: number,
) => {
  const emojiConfig = useMemo(() => ({tone: emojiTone}), [emojiTone])
  const emptyArray: [] = [] // constant reference to avoid re-running effects
  const {trigger: emojiTrigger, calculateSuggestions: calculateEmojiSuggestions} = useEmojiSuggestions(
    emojiSuggestions ?? emptyArray,
    emojiConfig,
  )
  const {trigger: mentionsTrigger, calculateSuggestions: calculateMentionSuggestions} = useMentionSuggestions(
    mentionSuggestions ?? emptyArray,
  )
  const {trigger: referencesTrigger, calculateSuggestions: calculateReferenceSuggestions} = useReferenceSuggestions(
    referenceSuggestions ?? emptyArray,
  )
  const triggersAndSuggestions = useMemo<TriggerAndSuggestions[]>(
    () => [
      {trigger: emojiTrigger, suggestionsCalculator: calculateEmojiSuggestions},
      {
        trigger: mentionsTrigger,
        suggestionsCalculator: calculateMentionSuggestions,
      },
      {
        trigger: referencesTrigger,
        suggestionsCalculator: calculateReferenceSuggestions,
      },
      slashCommandsConfig,
    ],
    [
      calculateEmojiSuggestions,
      calculateMentionSuggestions,
      calculateReferenceSuggestions,
      emojiTrigger,
      mentionsTrigger,
      referencesTrigger,
    ],
  )
  return useAutocompleteTriggersAndSuggestions(triggersAndSuggestions)
}
