import {ProgressBar, Spinner} from '@primer/react'
import {clsx} from 'clsx'

import type {UploadPlaceholderWidgetProps} from '../codemirror/widgets/upload-placeholder'
import styles from './UploadPlaceholder.module.css'

export function UploadPlaceholder({
  fileName,
  error,
  mediaKind,
  previewUrl,
  active,
  progressPercent,
  dimensions,
}: UploadPlaceholderWidgetProps) {
  const description = `Uploading ${fileName}...`

  // Errors are now shown in the banner position, not inline
  if (error) {
    return null
  }

  if (mediaKind && previewUrl && !active) {
    return (
      <div
        className={clsx(styles.mediaPreview, mediaKind === 'image' && styles.inline)}
        style={{
          '--UploadPlaceholder-progress': progressPercent !== undefined ? `${progressPercent / 100}` : 0,
        }}
        role="status"
      >
        {mediaKind === 'image' ? (
          <img src={previewUrl} alt={description} height={dimensions?.height} width={dimensions?.width} />
        ) : (
          <video
            src={previewUrl}
            controls={false}
            autoPlay={false}
            muted
            aria-label={description}
            className={styles.video}
          />
        )}

        <div className={styles.overlay}>
          <ProgressBar progress={progressPercent} barSize="large" animated className={styles.progress} />
        </div>
      </div>
    )
  }

  return (
    <span role="status">
      <span className={styles.spinner}>
        <Spinner size="small" style={{verticalAlign: 'text-top'}} />
      </span>{' '}
      {description}
    </span>
  )
}
