import {defaultKeymap, history, historyKeymap} from '@codemirror/commands'
import {type Command, EditorView, keymap, placeholder, type ViewUpdate} from '@codemirror/view'
import {readOnly} from '@github-ui/code-mirror/extensions/readonly'
import {ErrorBanner} from '@github-ui/markdown-editor/ErrorBanner'
import type {FileType} from '@github-ui/use-unified-file-select'
import {SkeletonText} from '@primer/react/experimental'
import {clsx} from 'clsx'
import {
  useCallback,
  useEffect,
  useEffectEvent,
  useImperativeHandle,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from 'react'

import {useAutocomplete} from './autocomplete/use-autocomplete'
import {caretFlashExtension} from './codemirror/extensions/caret-flash'
import {doubleClickSelectionExtension} from './codemirror/extensions/double-click-selection'
import {drawSelection} from './codemirror/extensions/draw-selection'
import {dropPositionExtension} from './codemirror/extensions/drop-position'
import {focusChanged, isFocused} from './codemirror/extensions/focused'
import {markdownContinuationExtension} from './codemirror/extensions/markdown-continuation'
import {markdownKeymapExtension} from './codemirror/extensions/markdown-keymap'
import {isModPressedField, modPressedExtension} from './codemirror/extensions/mod-pressed'
import {pasteLinksExtension} from './codemirror/extensions/paste-links'
import {proseExtension} from './codemirror/extensions/prose'
import {
  getCurrentSelectionContext,
  initialSelectionContext,
  selectionContextChanged,
  selectionContextExtension,
} from './codemirror/extensions/selection-context'
import {styleContentsExtension} from './codemirror/extensions/style-contents'
import {uploadPlaceholderExtension} from './codemirror/extensions/upload-placeholder'
import {visitLinkExtension} from './codemirror/extensions/visit-link'
import {useCompartment} from './codemirror/hooks/use-compartment'
import {useReactWidgets} from './codemirror/hooks/use-react-widgets'
import {UploadPlaceholderWidget} from './codemirror/widgets/upload-placeholder'
import {UploadPlaceholder} from './file-handler/UploadPlaceholder'
import {useFileHandler} from './file-handler/useFileHandler'
import styles from './HybridMarkdownEditor.module.css'
import type {HybridEditorTelemetry, ViewSwitchTrigger} from './telemetry'
import {useHybridEditorTelemetry} from './telemetry'
import {FileUploadButton} from './toolbar/FileUploadButton'
import {Header} from './toolbar/Header'
import {Toolbar} from './toolbar/Toolbar'
import type {HybridMarkdownEditorProps, MarkdownViewMode} from './types'

const DEFAULT_ACCEPTED_FILE_TYPES: FileType[] = ['image/*', 'video/*']

/** The actual CodeMirror hybrid editor internal implementation. */
export function CodeMirrorEditor({
  ref = null,
  value,
  onChange,
  disabled,
  onChangeViewMode,
  placeholder: placeholderText,
  'aria-describedby': ariaDescribedBy,
  acceptedFileTypes = DEFAULT_ACCEPTED_FILE_TYPES,
  onUploadFile,
  onFilesRejected,
  onPrimaryAction,
  referenceSuggestions,
  mentionSuggestions,
  emojiSuggestions,
  emojiTone,
  onInputFocus,
  customToolbarButtons,
  banner,
  isGenerating,
}: HybridMarkdownEditorProps) {
  const telemetry = useHybridEditorTelemetry()
  const trackKeyboardShortcut = useEffectEvent<HybridEditorTelemetry['trackKeyboardShortcut']>((...args) =>
    telemetry.trackKeyboardShortcut(...args),
  )

  const viewModeRef = useRef<MarkdownViewMode>('hybrid')
  const [selectedViewMode, setSelectedViewMode] = useState<MarkdownViewMode>('hybrid')

  const emitViewModeChange = useCallback(
    (nextViewMode: MarkdownViewMode, trigger: ViewSwitchTrigger = 'view_switcher') => {
      const previousViewMode = viewModeRef.current
      telemetry.trackViewSwitch({from: previousViewMode, to: nextViewMode, trigger})
      viewModeRef.current = nextViewMode
      setSelectedViewMode(nextViewMode)
      onChangeViewMode?.(nextViewMode)
    },
    [onChangeViewMode, telemetry],
  )

  const handleViewSwitchChange = useCallback(
    (nextViewMode: MarkdownViewMode) => emitViewModeChange(nextViewMode, 'view_switcher'),
    [emitViewModeChange],
  )

  const [selectionContext, setSelectionContext] = useState(initialSelectionContext)

  /** Tracks the expected value for the next render according to user input. */
  const [expectedValue, setExpectedValue] = useState(value)

  const onUpdate = useEffectEvent((update: ViewUpdate) => {
    if (update.docChanged) {
      const newValue = update.state.doc.toString()
      // As long as the consumer updates `value` state synchronously in its onChange handler, the next render will
      // have both `expectedValue` and `value` updated to the new value and will thus skip the reset step. If the
      // consumer ignores the update or changes `value` to something other than what was expected, we will reset
      // the editor, which will clear selection state. This 'synchronous update' requirement aligns with how React
      // handles regular DOM inputs (see https://react.dev/reference/react-dom/components/input#my-input-caret-jumps-to-the-beginning-on-every-keystroke).
      setExpectedValue(newValue)
      onChange?.(newValue)
    }

    // Check for selection context changes
    if (update.transactions.some(tr => selectionContextChanged(tr))) {
      const newContext = getCurrentSelectionContext(update.state)
      setSelectionContext(newContext)
    }

    // Emit event on focus
    if (update.transactions.some(tr => focusChanged(tr))) {
      if (isFocused(update.state)) onInputFocus?.()
    }
  })

  const [view, setView] = useState<EditorView | null>(null)

  const {autocompleteSuggestionsMenu, autocompleteKeymapCompartment, autocompleteListenerCompartment} = useAutocomplete(
    {
      view,
      setViewMode: useCallback(viewMode => emitViewModeChange(viewMode, 'slash_commands_hint'), [emitViewModeChange]),
      referenceSuggestions,
      mentionSuggestions,
      emojiSuggestions,
      emojiTone,
      telemetry,
      tabInsertsSuggestions: true,
    },
  )

  // Each extension that depends on prop values must be contained in a compartment to avoid reinitializing the editor
  // when the props change. Compartments are constant references so safe to use as dependencies.
  const placeholderCompartment = useCompartment(
    view,
    useMemo(() => placeholder(placeholderText ?? ''), [placeholderText]),
  )

  const readonlyCompartment = useCompartment(
    view,
    useMemo(() => (disabled ? readOnly() : []), [disabled]),
  )

  const a11yAttributesCompartment = useCompartment(
    view,
    useMemo(
      () =>
        EditorView.contentAttributes.of({
          'aria-label': 'Markdown content',
          ...(ariaDescribedBy ? {'aria-describedby': ariaDescribedBy} : {}),
        }),
      [ariaDescribedBy],
    ),
  )

  const primaryAction = useEffectEvent<Command>(() => {
    if (onPrimaryAction) {
      onPrimaryAction()
      return true
    }
    return false
  })

  const containerRef = useRef<HTMLDivElement>(null)

  const fileHandler = useFileHandler(
    {
      view,
      disabled,
      onUploadFile,
      acceptedFileTypes,
      onFilesRejected,
    },
    telemetry,
  )

  const uploadPlaceholderWidgets = useReactWidgets(containerRef, UploadPlaceholderWidget.widgetName, UploadPlaceholder)

  const initialValueRef = useRef(value)

  useEffect(
    function initializeCodeMirror() {
      const extensions = [
        doubleClickSelectionExtension, // Must be first to intercept double-click before other handlers
        proseExtension,
        styleContentsExtension,
        uploadPlaceholderExtension,
        dropPositionExtension,
        caretFlashExtension,
        drawSelection(),
        selectionContextExtension,
        pasteLinksExtension,
        markdownContinuationExtension,
        visitLinkExtension(),
        history(),
        EditorView.updateListener.of(onUpdate),
        autocompleteListenerCompartment,
        a11yAttributesCompartment,
        modPressedExtension,
        EditorView.contentAttributes.from(isModPressedField, isModPressed => ({
          class: clsx(isModPressed && styles.modPressed),
        })),
        placeholderCompartment,
        readonlyCompartment,
        markdownKeymapExtension({
          primaryAction,
          trackKeyboardShortcut,
        }),
        autocompleteKeymapCompartment,
        keymap.of(historyKeymap),
        keymap.of(defaultKeymap),
      ]

      const editorView = new EditorView({
        parent: containerRef.current!,
        doc: initialValueRef.current,
        extensions,
      })

      setView(editorView)

      return () => {
        editorView.destroy()
        setView(null)
      }
    },
    // IMPORTANT: These dependencies must not change during the lifecycle of the component. _Only_ compartments (from
    // `useCompartment`) and refs are safe to use here.
    [
      a11yAttributesCompartment,
      autocompleteKeymapCompartment,
      autocompleteListenerCompartment,
      placeholderCompartment,
      readonlyCompartment,
    ],
  )

  useLayoutEffect(
    function syncControlledValue() {
      // If the value prop doesn't match the expected value, overwrite the input with the prop value
      // Only happens if `onChange` is defined, indicating that this is a controlled input
      if (expectedValue !== value && onChange !== undefined) {
        view?.update([view.state.update({changes: {from: 0, to: view.state.doc.length, insert: value}})])
      }
    },
    [expectedValue, value, onChange, view],
  )

  useImperativeHandle(
    ref,
    () => ({
      view,
      focus: () => view?.focus(),
      reset: () => view?.dispatch({changes: {from: 0, to: view.state.doc.length, insert: ''}}),
      scrollIntoView: opts => view?.dom?.scrollIntoView(opts),
      moveCursorToEnd: () => view?.dispatch({selection: {anchor: view.state.doc.length}}),
      containerRef,
    }),
    [view],
  )

  return (
    <>
      <Header
        selectedView={selectedViewMode}
        onChangeViewMode={handleViewSwitchChange}
        uploadInProgress={fileHandler?.uploadInProgress ?? false}
      >
        <Toolbar
          view={view}
          selectedNodes={selectionContext}
          fileUploadButton={
            fileHandler ? (
              <FileUploadButton disabled={fileHandler.uploadInProgress} {...fileHandler.clickTargetProps} />
            ) : null
          }
          customButtons={customToolbarButtons}
        />
      </Header>

      <div className={styles.editorWrapper}>
        <div
          ref={containerRef}
          className={clsx(fileHandler?.isDraggedOver && styles.isDraggedOver, isGenerating && styles.generatingText)}
          {...fileHandler?.dropTargetProps}
          {...fileHandler?.pasteTargetProps}
        />
        {isGenerating && (
          <div
            className={styles.skeletonOverlay}
            role="status"
            data-testid="hybrid-editor-skeleton-overlay"
            aria-live="polite"
            aria-label="Generating text"
          >
            <SkeletonText lines={5} />
          </div>
        )}
      </div>

      {fileHandler?.errorMessage ? <ErrorBanner>{fileHandler.errorMessage}</ErrorBanner> : banner}

      {autocompleteSuggestionsMenu}
      {uploadPlaceholderWidgets}
    </>
  )
}
