import {EditorView} from '@codemirror/view'
import type {ImageDimensions} from '@github-ui/image-utils'
import {getImageSizeFromFile, RETINA_PPI} from '@github-ui/image-utils'
import {noop} from '@github-ui/noop'
import {useSafeAsyncCallback} from '@github-ui/use-safe-async-callback'
import {useTrackingRef} from '@github-ui/use-tracking-ref'
import type {FileType, UnifiedFileSelectResult} from '@github-ui/use-unified-file-select'
import {useUnifiedFileSelect} from '@github-ui/use-unified-file-select'
import type React from 'react'
import {type MouseEvent, type ReactNode, useCallback, useRef, useState} from 'react'

import {clearDropPosition, getDropPosition} from '../codemirror/extensions/drop-position'
import {
  addUploadPlaceholders,
  removeUploadPlaceholder,
  replaceUploadPlaceholder,
  updateUploadPlaceholder,
} from '../codemirror/extensions/upload-placeholder'
import {registerValidVideoUrl} from '../codemirror/extensions/video-registry'
import {htmlImage} from '../language-tools/html/builders'
import {markdownImage, markdownLink} from '../language-tools/markdown/builders'
import type {HybridEditorTelemetry} from '../telemetry'
import type {FileUploadResult} from '../types'

/** List of image MIME types which we do not attempt to render as images. */
const excludedImageMimeTypes = new Set(['image/bmp', 'image/tiff', 'image/heic', 'image/heif'])

const isImageFile = (file: File) =>
  file.type.toLowerCase().startsWith('image/') && !excludedImageMimeTypes.has(file.type.toLowerCase())
const isVideoFile = (file: File) => file.type.toLowerCase().startsWith('video/')

const normalizeUploadUrl = (url: string) => {
  const trimmed = url.trim()
  if (!trimmed) return trimmed

  if (typeof window === 'undefined' || !window.location?.origin) return trimmed

  try {
    return new URL(trimmed, window.location.origin).href
  } catch {
    return trimmed
  }
}

function calculateRenderedImageDimensions(originalDimensions: ImageDimensions) {
  if (originalDimensions.pixelsPerInch === RETINA_PPI) {
    return {
      width: Math.round(originalDimensions.width / 2),
      height: Math.round(originalDimensions.height / 2),
    }
  }

  return undefined // for non-retina, auto size to the original dimensions
}

const sizedMarkdownImage = (src: string, alt: string, dimensions?: Dimensions) => {
  return dimensions ? htmlImage(alt, src, dimensions.width, dimensions.height) : markdownImage(alt, src)
}

const markdown = (entry: PreparedUploadEntry, result: FileUploadResult) => {
  switch (entry.mediaKind) {
    case 'video':
      return result.url
    case 'image':
      return sizedMarkdownImage(result.url, 'Image', entry.dimensions)
    case undefined:
      return markdownLink(result.file.name, result.url)
  }
}

interface FileHandler extends UnifiedFileSelectResult {
  errorMessage?: React.ReactNode
  clearErrorMessage: () => void
  uploadInProgress: boolean
}

interface UseFileHandlingProps {
  view: EditorView | null
  disabled?: boolean
  onUploadFile?: (file: File, onProgress?: (progressBytes: number) => void) => Promise<FileUploadResult>
  acceptedFileTypes?: FileType[]
  onFilesRejected?: (files: File[], rejectedTypes: string[]) => void
}

type OptFileUploadResult = FileUploadResult | {url: null; file: File; error?: Error}

interface Dimensions {
  width: number
  height: number
}

interface PreparedUploadEntry {
  id: string
  file: File
  previewUrl?: string
  mediaKind?: 'image' | 'video'
  dimensions?: Dimensions
  error?: string
}

export const useFileHandler = (
  {view, disabled, onUploadFile, acceptedFileTypes, onFilesRejected}: UseFileHandlingProps,
  telemetry: HybridEditorTelemetry,
): FileHandler | null => {
  const placeholderIdRef = useRef(0)
  const [uploadInProgress, setUploadInProgress] = useState(false)
  const [errorMessage, setErrorMessage] = useState<ReactNode>(null)

  const viewRef = useTrackingRef(view)

  const updatePlaceholderProgress = useCallback(
    (entryId: string, progressPercent: number | undefined) => {
      if (viewRef.current) updateUploadPlaceholder(viewRef.current, {id: entryId, data: {progressPercent}})
    },
    [viewRef],
  )

  const insertPlaceholders = useCallback(
    (entries: PreparedUploadEntry[]) => {
      const editorView = viewRef.current
      if (!editorView || entries.length === 0) return

      // Determine where to insert the placeholder:
      // 1. Check if there's a drop position from a recent drop event (user dragged files)
      // 2. Fall back to the current selection start (user clicked upload button)
      let insertPos = getDropPosition(editorView.state)
      if (insertPos !== null) {
        // Clear the drop position so it's not reused for subsequent operations
        clearDropPosition(editorView)
      } else {
        // Fall back to the current selection start
        insertPos = editorView.state.selection.main.from
      }

      editorView.focus()

      addUploadPlaceholders(
        editorView,
        insertPos,
        ...entries.map(entry => ({
          id: entry.id,
          data: {
            fileName: entry.file.name,
            progressPercent: 0,
            previewUrl: entry.previewUrl,
            mediaKind: entry.mediaKind,
            dimensions: entry.dimensions,
            error: entry.error,
          },
        })),
      )
    },
    [viewRef],
  )

  // It's crucial that this is done safely because file uploads can take a long time - there's
  // a very good chance that the references will be outdated or the component unmounted by the time this is called.
  const handleCompletedFileUpload = useSafeAsyncCallback((entry: PreparedUploadEntry, result: OptFileUploadResult) => {
    const editorView = viewRef.current
    if (!editorView) return

    const replacement = result.url ? markdown(entry, result) : ''

    if (replacement) {
      replaceUploadPlaceholder(editorView, entry.id, replacement)

      // For video files, indicate that the URL from the server is likely valid so we can skip the video widget
      // loading state and avoid unnecessary flickering
      if (entry.mediaKind === 'video') {
        registerValidVideoUrl(editorView, result.url ?? '')
      }
    } else {
      const errorMsg =
        'error' in result && result.error !== undefined
          ? `Failed to upload "${entry.file.name}": ${result.error.message}`
          : `Failed to upload "${entry.file.name}"`

      // Remove the placeholder widget and show error in banner position instead
      removeUploadPlaceholder(editorView, entry.id)
      setErrorMessage(errorMsg)
    }

    // Clean up blob URL
    if (entry.previewUrl) {
      URL.revokeObjectURL(entry.previewUrl)
    }
  })

  const uploadFiles = useCallback(
    (entries: PreparedUploadEntry[]): Array<Promise<void>> =>
      entries.map(async entry => {
        // Provide a progress callback for the uploader to track upload progress
        const progressCallback = (progressBytes: number) => {
          const percent = entry.file.size > 0 ? Math.round((progressBytes / entry.file.size) * 100) : 0
          updatePlaceholderProgress(entry.id, Math.min(percent, 99)) // Cap at 99% until complete
        }

        let result: OptFileUploadResult = {url: null, file: entry.file}
        try {
          result = (await onUploadFile?.(entry.file, progressCallback)) ?? {file: entry.file, url: null}
        } catch (error) {
          result = {file: entry.file, url: null, error: error instanceof Error ? error : undefined}

          // rethrow asynchronously so the error is reported and logged
          setTimeout(() => {
            throw error
          })
        }

        result.url &&= normalizeUploadUrl(result.url)

        telemetry?.trackFileUpload({
          phase: result.url ? 'succeeded' : 'failed',
          mimeType: entry.file.type || 'unknown',
          sizeBytes: entry.file.size,
          mediaKind: entry.mediaKind ?? 'other',
          errorType: result.url ? undefined : 'upload',
        })

        handleCompletedFileUpload(entry, result)
      }),
    [onUploadFile, handleCompletedFileUpload, telemetry, updatePlaceholderProgress],
  )

  const onSelectFiles = useCallback(
    async (accepted: File[], rejected: File[]) => {
      // Clear any previous error when starting a new file selection
      setErrorMessage(null)

      const acceptedEntries = await Promise.all(
        accepted.map(async (file): Promise<PreparedUploadEntry> => {
          const id = `upload-placeholder-${placeholderIdRef.current++}`
          const mediaKind = isVideoFile(file) ? 'video' : isImageFile(file) ? 'image' : undefined
          const previewUrl = mediaKind ? URL.createObjectURL(file) : undefined

          let originalDimensions: ImageDimensions | null = null
          if (mediaKind === 'image') {
            try {
              originalDimensions = await getImageSizeFromFile(file)
            } catch (error) {
              // An error here doesn't need to be shown the user; we can still proceed with uploading the file.
              // We still rethrow it for logging:
              setTimeout(() => {
                throw error
              })
            }
          }

          return {
            id,
            file,
            previewUrl,
            mediaKind,
            dimensions: originalDimensions ? calculateRenderedImageDimensions(originalDimensions) : undefined,
          }
        }),
      )

      // Show rejected file errors in the banner (not as inline placeholders)
      if (rejected.length > 0) {
        const rejectedNames = rejected.map(f => f.name).join(', ')
        const errorMsg =
          rejected.length === 1
            ? `Cannot upload "${rejected[0]!.name}": File type is not supported`
            : `Cannot upload files: ${rejectedNames}. File types are not supported`
        setErrorMessage(errorMsg)
      }

      insertPlaceholders(acceptedEntries)

      for (const entry of acceptedEntries) {
        telemetry?.trackFileUpload({
          phase: 'selected',
          mimeType: entry.file.type || 'unknown',
          sizeBytes: entry.file.size,
          mediaKind: entry.mediaKind ?? 'other',
        })
      }

      if (rejected.length > 0) {
        const rejectedTypes = new Set(
          rejected
            .map(({name}) => {
              const parts = name.split('.')
              return parts.length > 1 ? `.${parts.at(-1)}` : ''
            })
            .filter(s => s !== ''),
        )

        onFilesRejected?.(rejected, [...rejectedTypes])
      }

      if (acceptedEntries.length > 0) {
        setUploadInProgress(true)
        try {
          await Promise.allSettled(uploadFiles(acceptedEntries))
        } finally {
          setUploadInProgress(false)
        }
      }
    },
    [onFilesRejected, insertPlaceholders, telemetry, uploadFiles],
  )

  const fileSelect = useUnifiedFileSelect({
    acceptedFileTypes,
    multi: true,
    // eslint-disable-next-line @typescript-eslint/no-misused-promises
    onSelect: onSelectFiles,
  })

  if (disabled || !view) {
    return {
      clickTargetProps: {
        onClick: noop,
      },
      dropTargetProps: {
        onDragEnter: noop,
        onDragLeave: noop,
        onDrop: noop,
        onDragOver: noop,
      },
      pasteTargetProps: {
        onPaste: noop,
      },
      isDraggedOver: false,
      uploadInProgress: false,
      clearErrorMessage: noop,
    }
  }

  // Add telemetry to click target
  const clickTargetProps = {
    ...fileSelect.clickTargetProps,
    onClick: (event: MouseEvent<HTMLButtonElement>) => {
      telemetry?.trackToolbarInteraction({
        control: 'attachment',
        action: 'attachment',
        trigger: 'toolbar',
        isActive: false,
        handled: true,
      })

      fileSelect.clickTargetProps.onClick(event)
    },
  }

  // Fix dragleave issue when dragging over child elements
  const dropTargetProps = {
    ...fileSelect.dropTargetProps,
    onDragLeave: (event: React.DragEvent<HTMLDivElement>) => {
      // Only call the original handler if the drag is truly leaving the container
      // Check if the relatedTarget (where the drag is moving to) is outside the container
      if (!(event.currentTarget as Node).contains(event.relatedTarget as Node)) {
        fileSelect.dropTargetProps.onDragLeave(event)
      }
    },
  }

  return onUploadFile
    ? {
        ...fileSelect,
        clickTargetProps,
        dropTargetProps,
        uploadInProgress,
        errorMessage,
        clearErrorMessage: () => setErrorMessage(null),
      }
    : null
}
