import {Prec} from '@codemirror/state'
import {type EditorView, keymap} from '@codemirror/view'
import {AutocompleteSuggestions} from '@github-ui/inline-autocomplete/AutocompleteSuggestions'
import type {Suggestion} from '@github-ui/inline-autocomplete/types'
import {getSuggestionKey} from '@github-ui/inline-autocomplete/utils'
import type {SuggestionOptions} from '@github-ui/markdown-editor/suggestions'
import type {Emoji} from '@github-ui/markdown-editor/suggestions/use-emoji-suggestions'
import type {Mentionable} from '@github-ui/markdown-editor/suggestions/use-mention-suggestions'
import type {Reference} from '@github-ui/markdown-editor/suggestions/use-reference-suggestions'
import {useId, useMemo} from 'react'

import {autocompleteListenerExtension} from '../codemirror/extensions/autocomplete-listener'
import {useCompartment} from '../codemirror/hooks/use-compartment'
import type {HybridEditorTelemetry} from '../telemetry'
import type {MarkdownViewMode} from '../types'
import {useAutocompleteState} from './use-autocomplete-state'
import {useStandardAutocompleteConfig} from './use-standard-autocomplete-config'

interface UseAutocompleteProps {
  view: EditorView | null
  setViewMode: (mode: MarkdownViewMode) => void
  referenceSuggestions?: SuggestionOptions<Reference>
  mentionSuggestions?: SuggestionOptions<Mentionable>
  emojiSuggestions?: SuggestionOptions<Emoji>
  emojiTone?: number
  telemetry?: HybridEditorTelemetry
  tabInsertsSuggestions?: boolean
}

export const useAutocomplete = ({
  view,
  setViewMode,
  referenceSuggestions,
  mentionSuggestions,
  emojiSuggestions,
  emojiTone,
  telemetry,
  tabInsertsSuggestions = false,
}: UseAutocompleteProps) => {
  const {triggers, suggestions, setSuggestionEvent} = useStandardAutocompleteConfig(
    referenceSuggestions,
    mentionSuggestions,
    emojiSuggestions,
    emojiTone,
  )

  const {
    activeSuggestion,
    autocompleteKeymap,
    autocompleteVisible,
    insertAutocompleteSelection,
    setAutocompleteVisible,
    setTriggerCharCoords,
    showEventRef,
    triggerCharCoords,
  } = useAutocompleteState({
    suggestions,
    setSuggestionEvent,
    setViewMode,
    telemetry,
  })

  const listId = useId()
  const getSuggestionId = (suggestion: Suggestion) => `${listId}-${getSuggestionKey(suggestion)}`

  const onCommit = (suggestion = activeSuggestion) => {
    if (!view || !suggestion) return
    insertAutocompleteSelection(view, suggestion)
  }

  // Use a compartment since we only want these keybindings when autocomplete suggestions are visible (i.e. the
  // compartment automatically reconfigures on that state change).
  const autocompleteKeymapCompartment = useCompartment(
    view,
    useMemo(
      () => (autocompleteVisible ? Prec.highest(keymap.of(autocompleteKeymap)) : []),
      [autocompleteVisible, autocompleteKeymap],
    ),
  )

  const autocompleteListenerCompartment = useCompartment(
    view,
    useMemo(
      () =>
        autocompleteListenerExtension(
          setSuggestionEvent,
          setAutocompleteVisible,
          setTriggerCharCoords,
          triggers,
          showEventRef,
        ),
      [setSuggestionEvent, setAutocompleteVisible, setTriggerCharCoords, triggers, showEventRef],
    ),
  )

  const hasSuggestions = suggestions !== null && suggestions.length > 0

  const inputRef = useMemo(() => ({current: {focus: () => view?.focus()}}), [view])

  return {
    autocompleteSuggestionsMenu: (
      <AutocompleteSuggestions
        id={listId}
        suggestions={suggestions}
        inputRef={inputRef}
        onCommit={onCommit}
        onClose={() => {
          setAutocompleteVisible(false)
        }}
        triggerCharCoords={triggerCharCoords}
        visible={autocompleteVisible && hasSuggestions}
        defaultPlacement="below"
        activeSuggestion={activeSuggestion}
        getSuggestionId={getSuggestionId}
        role="listbox"
        tabInsertsSuggestions={tabInsertsSuggestions}
      />
    ),
    autocompleteKeymapCompartment,
    autocompleteListenerCompartment,
  }
}
